SELECT (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='bk_memory' AND ((table_name='memory_rag_lock' AND column_name='lock_id') OR (table_name='memory_rag_projection' AND column_name IN ('space_id','document_id','revision','tombstone','event_payload')) OR (table_name='memory_rag_outbox' AND column_name IN ('event_id','space_id','document_id','revision','event_payload','state','attempts','next_attempt_at','error_code','created_at'))))=16 AND (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='bk_memory' AND table_name IN ('memory_rag_lock','memory_rag_projection','memory_rag_outbox') AND engine='InnoDB')=3 AND EXISTS(SELECT 1 FROM bk_memory.memory_rag_lock WHERE lock_id=1);
